# Generated from TelegramOnly/scripts/reset_telegramonly.py; keep the reset engine identical.
SCRIPT_SOURCE = '#!/usr/bin/env python3\n"""Debian stack reset: inspect first, then archive explicitly confirmed components.\n\nNo package autoremove, firewall reset, SSH changes or global Docker prune.\nThis module is also shipped inside VPNserverManage for its server-card action.\n"""\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport shutil\nimport socket\nimport subprocess\nimport sys\nimport tarfile\nimport time\n\nVERSION = 1\nAPP_ROOTS = ("/opt/TelegramOnly", "/opt/TelegramSimple")\nCOMPONENTS = {\n    "bot": {\n        "units": ["telegramonly.service", "telegramonly-maintenance.timer", "telegramonly-maintenance.service"],\n        "paths": list(APP_ROOTS),\n    },\n    "mieru": {"units": ["mita.service"], "paths": ["/etc/mita", "/etc/mieru", "/var/lib/mita"]},\n    "naiveproxy": {"units": ["caddy-naive.service"], "paths": ["/etc/caddy-naive", "/var/lib/caddy-naive", "/usr/local/bin/caddy-naive"]},\n    "hysteria2": {"units": ["hysteria-server.service"], "paths": ["/etc/hysteria", "/usr/local/bin/hysteria"]},\n    "vless": {"units": ["xray.service", "x-ui.service"], "paths": ["/usr/local/etc/xray", "/usr/local/bin/xray", "/usr/local/share/xray", "/usr/local/x-ui", "/etc/x-ui"]},\n    "mtproto": {"units": ["mtproto-proxy.service"], "paths": ["/etc/mtproto-proxy", "/usr/local/bin/mtproto-proxy", "/opt/MTProxy"]},\n    "ha": {"units": ["ha-stub-grpc.service", "ha-stub-udp.service", "ha-reticulum-bridge.service", "ha-adapter-grpc.service", "ha-rns-watchdog.timer", "ha-rns-watchdog.service"], "paths": ["/etc/shskm/ha-adapter.env", "/usr/local/bin/ha-rns-watchdog.sh"]},\n}\nPROTECTED_SERVICES = {"headscale", "headplane", "tailscale"}\nPRESERVED = [\n    "Debian, SSH, users, authorized_keys, firewall, routes, sysctl, swap, journald settings",\n    "Docker engine/images, system Python/Go, shared apt packages",\n    "Tailscale/Headscale/Headplane and monitoring used for server access",\n    "Unrelated containers, volumes and applications; nonstandard installations require manual review",\n]\n\n\ndef run(args, *, check=True):\n    result = subprocess.run(args, capture_output=True, text=True, timeout=90)\n    if check and result.returncode:\n        # WARNING: external stderr and service definitions may contain secrets.\n        raise RuntimeError("Command failed: " + args[0] + " (details suppressed)")\n    return result\n\n\ndef selected_components(value):\n    names = sorted(set(value.split(",")))\n    if not names or any(name not in COMPONENTS for name in names):\n        raise ValueError("Select components from: " + ", ".join(COMPONENTS))\n    return names\n\n\ndef fingerprint(plan):\n    return hashlib.sha256(json.dumps(plan, sort_keys=True, separators=(",", ":")).encode()).hexdigest()\n\n\ndef path_record(path):\n    target = Path(path)\n    if not target.exists() and not target.is_symlink():\n        return None\n    # Never follow aliases to an unrelated installation or filesystem mount.\n    if target.is_symlink() or str(target.resolve()) != path or os.path.ismount(path):\n        raise ValueError("Unsafe or mounted target: " + path)\n    info = target.stat()\n    return {"path": path, "device": info.st_dev, "inode": info.st_ino}\n\n\ndef owned_directory(directory):\n    return any(directory == root or directory.startswith(root + "/") for root in APP_ROOTS)\n\n\ndef docker_inventory():\n    if not shutil.which("docker"):\n        return [], []\n    # If Docker exists but is inaccessible, fail closed instead of missing containers.\n    ids = run(["docker", "ps", "-aq"]).stdout.split()\n    containers = []\n    for cid in ids:\n        item = json.loads(run(["docker", "inspect", cid]).stdout)[0]\n        labels = item.get("Config", {}).get("Labels") or {}\n        service = labels.get("com.docker.compose.service", "")\n        directory = labels.get("com.docker.compose.project.working_dir", "")\n        mounts = [{"type": m.get("Type"), "source": m.get("Source", ""), "name": m.get("Name", "")} for m in item.get("Mounts", [])]\n        containers.append({"id": cid, "name": item.get("Name", "").lstrip("/"),\n                           "owned": owned_directory(directory), "service": service, "mounts": mounts})\n    volumes = []\n    for name in run(["docker", "volume", "ls", "-q"]).stdout.split():\n        item = json.loads(run(["docker", "volume", "inspect", name]).stdout)[0]\n        # Only volumes actually mounted by selected containers are considered later.\n        volumes.append({"name": name, "mountpoint": item.get("Mountpoint", ""), "driver": item.get("Driver")})\n    return containers, volumes\n\n\ndef inspect(selected):\n    plan = {"version": VERSION, "hostname": socket.gethostname(), "components": selected,\n            "units": [], "paths": [], "containers": [], "volumes": [], "blockers": [], "preserved": PRESERVED}\n    machine = Path("/etc/machine-id")\n    plan["machine"] = hashlib.sha256(machine.read_bytes()).hexdigest() if machine.exists() else "unknown"\n    paths = set()\n    for component in selected:\n        for unit in COMPONENTS[component]["units"]:\n            fragment = run(["systemctl", "show", unit, "--property=FragmentPath", "--value"]).stdout.strip()\n            if not fragment:\n                continue\n            allowed = {f"{base}/{unit}" for base in ("/etc/systemd/system", "/lib/systemd/system", "/usr/lib/systemd/system")}\n            if fragment not in allowed:\n                plan["blockers"].append("Nonstandard unit path: " + unit)\n                continue\n            plan["units"].append({"name": unit, "fragment": fragment})\n            # Packaged units stay installed/disabled; only custom units are archived.\n            if fragment.startswith("/etc/systemd/system/"):\n                paths.add(fragment)\n            paths.add("/etc/systemd/system/" + unit + ".d")\n        paths.update(COMPONENTS[component]["paths"])\n    for path in sorted(paths):\n        try:\n            record = path_record(path)\n            if record:\n                if path in APP_ROOTS and not (Path(path) / "scripts/install_telegramonly_vps.sh").is_file():\n                    plan["blockers"].append("Missing TelegramOnly installation marker: " + path)\n                else:\n                    plan["paths"].append(record)\n        except ValueError as exc:\n            plan["blockers"].append(str(exc))\n    # A retained HA service may still execute code from the bot\'s checkout.\n    if "bot" in selected and "ha" not in selected:\n        for unit in COMPONENTS["ha"]["units"]:\n            directory = run(["systemctl", "show", unit, "--property=WorkingDirectory", "--value"]).stdout.strip()\n            if owned_directory(directory):\n                plan["blockers"].append("Retained service uses project directory: " + unit)\n    containers, volumes = docker_inventory()\n    selected_ids = set()\n    if "bot" in selected:\n        for item in containers:\n            if item["owned"] and item["service"] not in PROTECTED_SERVICES:\n                selected_ids.add(item["id"])\n                plan["containers"].append({"id": item["id"], "name": item["name"]})\n    for item in containers:\n        if item["id"] not in selected_ids:\n            for mount in item["mounts"]:\n                for record in plan["paths"]:\n                    root = record["path"]\n                    if mount["source"] == root or mount["source"].startswith(root + "/"):\n                        plan["blockers"].append("Retained container uses target: " + item["name"] + " -> " + root)\n    volume_names = {m["name"] for c in containers if c["id"] in selected_ids for m in c["mounts"] if m["type"] == "volume"}\n    for volume in volumes:\n        if volume["name"] not in volume_names:\n            continue\n        shared = any(c["id"] not in selected_ids and any(m["name"] == volume["name"] for m in c["mounts"]) for c in containers)\n        if shared or volume["driver"] != "local":\n            plan["blockers"].append("Shared/non-local volume: " + volume["name"])\n        else:\n            plan["volumes"].append(volume)\n    # Catch nested bind mounts; rename across mounted filesystems is not a reset.\n    mounts = run(["findmnt", "--json", "--list", "--output", "TARGET"]).stdout\n    for mount in json.loads(mounts).get("filesystems", []):\n        target = mount.get("target", "")\n        if any(target.startswith(p["path"] + "/") for p in plan["paths"]):\n            plan["blockers"].append("Nested mount beneath target: " + target)\n    # Stop timers first so they cannot reactivate a service during archival.\n    plan["units"].sort(key=lambda x: (not x["name"].endswith(".timer"), x["name"]))\n    plan["containers"].sort(key=lambda x: x["id"])\n    plan["volumes"].sort(key=lambda x: x["name"])\n    plan["blockers"] = sorted(set(plan["blockers"]))\n    plan["plan_hash"] = fingerprint(plan)\n    return plan\n\n\ndef apply(selected, plan_hash, confirmation):\n    import fcntl\n    if os.geteuid() != 0:\n        raise ValueError("Apply requires root")\n    os.umask(0o077)\n    with open("/run/lock/telegramonly-reset.lock", "w") as lock:\n        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n        plan = inspect(selected)\n        if plan["blockers"]:\n            raise ValueError("Plan has blockers; no changes performed")\n        if confirmation != plan["hostname"] or plan_hash != plan["plan_hash"]:\n            raise ValueError("Host confirmation or plan hash changed; inspect again")\n        base = Path("/var/backups/telegramonly-reset")\n        if base.is_symlink():\n            raise ValueError("Backup directory must not be a symlink")\n        base.mkdir(mode=0o700, parents=True, exist_ok=True)\n        os.chmod(base, 0o700)\n        backup = base / (time.strftime("%Y%m%d-%H%M%S") + "-" + plan_hash[:12])\n        backup.mkdir(mode=0o700)\n        journal = {"plan": plan, "completed": [], "status": "running"}\n\n        def record(action):\n            journal["completed"].append(action)\n            target = backup / "manifest.json"\n            # Root-only directory; no secret contents are included in the manifest.\n            target.write_text(json.dumps(journal, indent=2), encoding="utf-8")\n            os.chmod(target, 0o600)\n\n        record("backup-created")\n        try:\n            for unit in plan["units"]:\n                run(["systemctl", "stop", unit["name"]])\n                run(["systemctl", "disable", unit["name"]])\n                record("stopped " + unit["name"])\n            for container in plan["containers"]:\n                run(["docker", "stop", "--time", "30", container["id"]])\n                record("stopped container " + container["name"])\n            # Archive volumes BEFORE removing containers or data. Abort on backup failure.\n            for volume in plan["volumes"]:\n                source = Path(volume["mountpoint"])\n                if not source.is_dir() or source.is_symlink():\n                    raise ValueError("Volume mountpoint is unavailable")\n                archive = backup / ("volume-" + hashlib.sha256(volume["name"].encode()).hexdigest()[:16] + ".tar")\n                with tarfile.open(archive, "w", dereference=False) as tar:\n                    tar.add(source, arcname="data", recursive=True)\n                os.chmod(archive, 0o600)\n                with tarfile.open(archive) as tar:\n                    tar.getmembers()\n                record("archived volume " + volume["name"] + " -> " + archive.name)\n            for container in plan["containers"]:\n                run(["docker", "rm", container["id"]])\n                record("removed container " + container["name"])\n            for volume in plan["volumes"]:\n                run(["docker", "volume", "rm", volume["name"]])\n                record("removed volume " + volume["name"])\n            for item in plan["paths"]:\n                source = Path(item["path"])\n                if path_record(str(source)) != item:\n                    raise ValueError("Target changed during reset")\n                destination = backup / "files" / str(source).lstrip("/")\n                destination.parent.mkdir(parents=True, exist_ok=True, mode=0o700)\n                # Rename, never rm -rf. Cross-device moves are refused to preserve data.\n                if source.stat().st_dev != destination.parent.stat().st_dev:\n                    raise ValueError("Cross-filesystem archival requires manual handling")\n                source.rename(destination)\n                record("archived " + str(source))\n            run(["systemctl", "daemon-reload"])\n            journal["status"] = "complete"\n            record("complete")\n        except Exception:\n            journal["status"] = "incomplete"\n            record("stopped on error; inspect manifest before retrying")\n            return {"success": False, "backup": str(backup), "error": "Reset incomplete; review private manifest. Some services may be stopped."}\n        return {"success": True, "backup": str(backup), "preserved": PRESERVED}\n\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--components", default=",".join(COMPONENTS))\n    parser.add_argument("--apply", action="store_true")\n    parser.add_argument("--plan-hash", default="")\n    parser.add_argument("--confirm", default="", help="Exact hostname from the inspected plan")\n    args = parser.parse_args(argv)\n    try:\n        if sys.platform != "linux" or not Path("/etc/debian_version").exists():\n            raise ValueError("Debian/Ubuntu Linux required")\n        if os.geteuid() != 0:\n            raise ValueError("Run with sudo for a complete inventory")\n        selected = selected_components(args.components)\n        result = apply(selected, args.plan_hash, args.confirm) if args.apply else inspect(selected)\n        print(json.dumps(result, ensure_ascii=False, indent=2))\n        return 1 if result.get("success") is False or result.get("blockers") else 0\n    except Exception as exc:\n        # Do not return tracebacks/SSH credentials or unfiltered external command output.\n        print(json.dumps({"success": False, "error": str(exc) if isinstance(exc, ValueError) else "Inspection/reset failed; no automatic retry"}))\n        return 1\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
